function check([target], actual) {
  if (typeof actual !== 'string') return false;
  const board = ['abcde', 'fghij', 'klmno', 'pqrst', 'uvwxy', 'z'];
  // The shortest length: every letter costs its grid distance from the previous one, plus one '!'.
  let shortest = target.length, fromRow = 0, fromCol = 0;
  for (const letter of target) {
    const index = letter.charCodeAt(0) - 97;
    shortest += Math.abs(Math.floor(index / 5) - fromRow) + Math.abs(index % 5 - fromCol);
    fromRow = Math.floor(index / 5);
    fromCol = index % 5;
  }
  if (actual.length !== shortest) return false;
  let row = 0, col = 0, written = '';
  for (const move of actual) {
    if (move === 'U') row--;
    else if (move === 'D') row++;
    else if (move === 'L') col--;
    else if (move === 'R') col++;
    else if (move === '!') written += board[row][col];
    else return false;
    if (row < 0 || row >= board.length || col < 0 || col >= board[row].length) return false;
  }
  return written === target;
}

