function validate([target]) {
  if (typeof target !== 'string' || target.length < 1 || target.length > 100) return 'target needs 1 to 100 letters.';
  if (!/^[a-z]+$/.test(target)) return 'target uses lowercase English letters only.';
  return null;
}

