function alphabetBoardPath(target) {
  let row = 0;
  let col = 0;
  const moves = [];
  for (const letter of target) {
    const index = letter.charCodeAt(0) - 97;
    const goalRow = Math.floor(index / 5);
    const goalCol = index % 5;
    // Up and left come first, so the cursor never lands on a missing cell of the short last row.
    while (row > goalRow) {
      moves.push('U');
      row--;
    }
    while (col > goalCol) {
      moves.push('L');
      col--;
    }
    while (row < goalRow) {
      moves.push('D');
      row++;
    }
    while (col < goalCol) {
      moves.push('R');
      col++;
    }
    moves.push('!');
  }
  return moves.join('');
}

