function alphabetBoardPath(target) {
  // Breadth-first search over the real cells for every letter, then rebuild the path.
  const board = ['abcde', 'fghij', 'klmno', 'pqrst', 'uvwxy', 'z'];
  const steps = [['D', 1, 0], ['R', 0, 1], ['U', -1, 0], ['L', 0, -1]];
  let r = 0, c = 0, out = '';
  for (const ch of target) {
    const parent = new Map([[r * 5 + c, null]]);
    const queue = [[r, c]];
    let found = null;
    while (queue.length) {
      const [x, y] = queue.shift();
      if (board[x][y] === ch) { found = [x, y]; break; }
      for (const [move, dx, dy] of steps) {
        const nx = x + dx, ny = y + dy;
        if (nx < 0 || nx >= board.length || ny < 0 || ny >= board[nx].length) continue;
        if (parent.has(nx * 5 + ny)) continue;
        parent.set(nx * 5 + ny, [x * 5 + y, move]);
        queue.push([nx, ny]);
      }
    }
    let path = '', key = found[0] * 5 + found[1];
    while (parent.get(key)) { const [previous, move] = parent.get(key); path = move + path; key = previous; }
    out += path + '!';
    [r, c] = found;
  }
  return out;
}

