function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  // Lean on the corner letters, where a careless path walks off the board.
  const tricky = 'zzzuvyejt';
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 8);
  let target = '';
  for (let i = 0; i < n; i++) {
    target += rand() < 0.4 ? tricky[Math.floor(rand() * tricky.length)] : letters[Math.floor(rand() * 26)];
  }
  return [target];
}
